// and preserves object lifetime without requiring Arduino-specific types.

// Construct a new BlinkerDebug instance using the default constructor.
BlinkerDebug *dbg = new BlinkerDebug();
if (!dbg) { FUZZ_BAIL(); }

// Immediately after default construction, no Stream is configured and isInit is false.
// Therefore, querying debug state must report disabled.
bool any = dbg->isDebug();
bool all = dbg->isDebugAll();
if (any) { FUZZ_ASSERT(false, "Fresh BlinkerDebug must not be in debug mode before stream() is called"); }
if (all) { FUZZ_ASSERT(false, "Fresh BlinkerDebug must not be in ALL debug mode before stream() is called"); }

// Track initialization status for downstream stubs (0 = stream() has not been called)
FUZZ_SET_ATTR_INT(dbg, "init", 0);

// Optionally, flip internal level to _debug_all without initializing stream to broaden coverage of state transitions.
// This must not make isDebug()/isDebugAll() return true because isInit remains false by design.
