if ((choose & 1u) == 1u) {
    dbg->debugAll();
    if (dbg->isDebug()) { FUZZ_ASSERT(false, "debugAll without stream() must not enable isDebug"); }
    if (dbg->isDebugAll()) { FUZZ_ASSERT(false, "debugAll without stream() must not enable isDebugAll"); }
}

